SELECT DISTINCT t0."interval" AS "interval", t0."at" AS "at" FROM "ended_at" AS t0 JOIN "std_time_reference_point_position" AS t1 ON t1."id" = t0."at" JOIN "interval__extension_end" AS t2 ON t2."id" = t0."interval" WHERE t1."v" < t2."v";

CREATE MATERIALIZED VIEW "interval_inverted" AS
SELECT DISTINCT t0."id" AS "interval" FROM "std_time_interval_start" AS t0 JOIN "std_time_interval_end" AS t1 ON t1."id" = t0."id" WHERE t1."v" <= t0."v";

CREATE MATERIALIZED VIEW "known_at" AS
SELECT DISTINCT t0."id" AS "interval", t1."id" AS "at" FROM "std_time_interval_on_axis" AS t0 JOIN "std_time_reference_point_on_axis" AS t1 ON t1."v" = t0."v" JOIN "std_time_reference_point_position" AS t2 ON t2."id" = t1."id" JOIN "interval__known_from" AS t3 ON t3."id" = t0."id" WHERE t3."v" <= t2."v";

CREATE MATERIALIZED VIEW "known_from_stated" AS
SELECT DISTINCT t0."id" AS "interval" FROM "interval__known_from" AS t0;

CREATE MATERIALIZED VIEW "ledger_line" AS
SELECT DISTINCT t1."v" AS "application", t0."id" AS "payment", t2."v" AS "cents" FROM "ledger_payment__accepted" AS t0 JOIN "ledger_payment__application" AS t1 ON t1."id" = t0."id" JOIN "ledger_payment__amount" AS t2 ON t2."id" = t0."id";

CREATE MATERIALIZED VIEW "ledger_line__witness" AS
SELECT DISTINCT t1."v" AS "v_a", t2."v" AS "v_c", t0."id" AS "v_p" FROM "ledger_payment__accepted" AS t0 JOIN "ledger_payment__application" AS t1 ON t1."id" = t0."id" JOIN "ledger_payment__amount" AS t2 ON t2."id" = t0."id";

CREATE MATERIALIZED VIEW "looked_up" AS
SELECT DISTINCT t0."id" AS "lookup" FROM "status_lookup__credential" AS t0
UNION
SELECT DISTINCT t0."id" AS "lookup" FROM "status_lookup__statement" AS t0;

CREATE MATERIALIZED VIEW "stated" AS
SELECT DISTINCT t0."id" AS "statement", t0."v" AS "node", t1."v" AS "identifier", t2."v" AS "other_node", t3."v" AS "other_identifier" FROM "identity_statement__first_node" AS t0 JOIN "identity_statement__first_identifier" AS t1 ON t1."id" = t0."id" JOIN "identity_statement__second_node" AS t2 ON t2."id" = t0."id" JOIN "identity_statement__second_identifier" AS t3 ON t3."id" = t0."id"
UNION
SELECT DISTINCT t0."id" AS "statement", t2."v" AS "node", t3."v" AS "identifier", t0."v" AS "other_node", t1."v" AS "other_identifier" FROM "identity_statement__first_node" AS t0 JOIN "identity_statement__first_identifier" AS t1 ON t1."id" = t0."id" JOIN "identity_statement__second_node" AS t2 ON t2."id" = t0."id" JOIN "identity_statement__second_identifier" AS t3 ON t3."id" = t0."id";

CREATE MATERIALIZED VIEW "stated_1__witness" AS
SELECT DISTINCT t2."v" AS "v_m", t0."v" AS "v_n", t0."id" AS "v_s", t1."v" AS "v_x", t3."v" AS "v_y" FROM "identity_statement__first_node" AS t0 JOIN "identity_statement__first_identifier" AS t1 ON t1."id" = t0."id" JOIN "identity_statement__second_node" AS t2 ON t2."id" = t0."id" JOIN "identity_statement__second_identifier" AS t3 ON t3."id" = t0."id";

CREATE MATERIALIZED VIEW "stated_2__witness" AS
SELECT DISTINCT t2."v" AS "v_m", t0."v" AS "v_n", t0."id" AS "v_s", t1."v" AS "v_x", t3."v" AS "v_y" FROM "identity_statement__first_node" AS t0 JOIN "identity_statement__first_identifier" AS t1 ON t1."id" = t0."id" JOIN "identity_statement__second_node" AS t2 ON t2."id" = t0."id" JOIN "identity_statement__second_identifier" AS t3 ON t3."id" = t0."id";

CREATE MATERIALIZED VIEW "names_here" AS
SELECT DISTINCT t0."id" AS "credential", t2."statement" AS "statement", t2."other_identifier" AS "person" FROM "credential__issuer" AS t0 JOIN "credential__subject" AS t1 ON t1."id" = t0."id" JOIN "stated" AS t2 ON t2."node" = t0."v" AND t2."identifier" = t1."v" AND t2."other_node" = 'https://municipality.invented.example';

CREATE MATERIALIZED VIEW "named_here" AS
SELECT DISTINCT t0."credential" AS "credential" FROM "names_here" AS t0;

CREATE MATERIALIZED VIEW "paid" AS
SELECT DISTINCT t0."application" AS "application" FROM "ledger_line" AS t0;

CREATE MATERIALIZED VIEW "proposal" AS
SELECT DISTINCT t0."id" AS "decision" FROM "decision__state" AS t0 WHERE t0."v" = 'proposed';

CREATE MATERIALIZED VIEW "proposal__witness" AS
SELECT DISTINCT t0."id" AS "v_d" FROM "decision__state" AS t0 WHERE t0."v" = 'proposed';

CREATE MATERIALIZED VIEW "repeat_application" AS
SELECT DISTINCT t0."household" AS "household", t0."n" AS "n" FROM "application_count" AS t0 WHERE t0."n" >= CAST(2 AS BIGINT);

CREATE MATERIALIZED VIEW "repeat_application__witness" AS
SELECT DISTINCT t0."household" AS "v_h", t0."n" AS "v_n" FROM "application_count" AS t0 WHERE t0."n" >= CAST(2 AS BIGINT);

CREATE MATERIALIZED VIEW "took_effect" AS
SELECT DISTINCT t0."id" AS "decision", t1."id" AS "on" FROM "decision" AS t0 JOIN "reference_date__day" AS t1 ON TRUE JOIN "decision__valid_from_day" AS t2 ON t2."id" = t0."id" LEFT JOIN "decision__state" AS n0 ON n0."id" = t0."id" AND n0."v" = 'proposed' WHERE t2."v" <= t1."v" AND n0."id" IS NULL;

CREATE MATERIALIZED VIEW "replaced" AS
SELECT DISTINCT t0."v" AS "decision", t0."id" AS "by", t1."on" AS "on" FROM "decision__supersedes" AS t0 JOIN "took_effect" AS t1 ON t1."decision" = t0."id";

CREATE MATERIALIZED VIEW "replaced__witness" AS
SELECT DISTINCT t0."v" AS "v_d", t1."on" AS "v_r", t0."id" AS "v_s" FROM "decision__supersedes" AS t0 JOIN "took_effect" AS t1 ON t1."decision" = t0."id";

DECLARE RECURSIVE VIEW "replaces" ("a" VARCHAR NOT NULL, "b" VARCHAR NOT NULL);

CREATE MATERIALIZED VIEW "replaces" AS
SELECT DISTINCT t0."id" AS "a", t0."v" AS "b" FROM "decision__supersedes" AS t0
UNION
SELECT DISTINCT t0."a" AS "a", t1."v" AS "b" FROM "replaces" AS t0 JOIN "decision__supersedes" AS t1 ON t1."id" = t0."b";

CREATE MATERIALIZED VIEW "scoped" AS
SELECT DISTINCT t0."id" AS "statement" FROM "identity_statement__first_node" AS t0 JOIN "identity_statement__second_node" AS t1 ON t1."id" = t0."id" JOIN "statement_scope" AS t2 ON t2."statement" = t0."id" AND t2."node" = t0."v" JOIN "statement_scope" AS t3 ON t3."statement" = t0."id" AND t3."node" = t1."v";

CREATE TABLE "epoch__in" (e BIGINT NOT NULL);

